    "A month of levered longs at 0.15% a day costs $4,050 on $90K of notional before the price moves at all, and launch-week funding on a genuinely hot listing routinely runs several times that. Held all 258 days it comes to $10,206 on the two-rate model below. Spot bids over the same month cost nothing to hold. The playbook does not distinguish between the two, and at the $3–5B band — “stretch bids over a month or more” — that distinction is most of the cost.": "0.15%로 한 달간 레버리지 롱을 들면 명목가치 $90K에 $4,050이 듭니다. 가격이 움직이기도 전에요. 그리고 진짜 뜨거운 상장의 첫 주 펀딩은 보통 그 몇 배로 뛰어오릅니다. 258일 내내 들고 있으면 아래 두 단계 요율 모델 기준 $10,206입니다. 같은 한 달을 현물로 받쳐두면 보유 비용은 들지 않습니다. 플레이북은 둘을 구분하지 않는데, $3–5B 밴드 — “한 달 이상에 걸친 호가 분산” — 에서는 그 차이가 비용의 대부분입니다.",
