    "All three series are rescaled to 0–100 inside their own range, so only the": "세 시리즈 모두 자기 범위 안에서 0–100으로 재조정했으므로 비교 가능한 것은 움직임의",
    "Hover a column for the day's open, high, low, close and the book that day.": "막대에 마우스를 올리면 그날의 시가·고가·저가·종가와 그날의 장부가 나옵니다.",
    "Non-treasury pool · $36,315,006 (82.6%) before costs, rewards, and OLP PnL": "트레저리 외 풀 · $36,315,006 (82.6%) 비용·보상·OLP 손익 반영 전",
    "On-chain USDC balance deltas · non-revenue transfers may affect the result": "온체인 USDC 잔고 증감 · 매출이 아닌 이체가 결과에 영향을 줄 수 있음",
    "Open interest by venue, traditional and crypto halves, on one dollar scale": "거래소별 미결제약정, 전통과 크립토로 나눠 하나의 달러 눈금에",
    "30 daily clips of $5K, 1.5× target, liquidation −65.8% below average entry.": "하루 $5K씩 30회 분할, 목표 1.5배, 청산가는 평균 진입가 대비 −65.8%.",
    "Current treasury balance · $7,660,006 (17.4% of modeled historical spreads)": "현재 트레저리 잔고 · $7,660,006 (모델 기준 누적 스프레드의 17.4%)",
    "Gains Network · FDV $12M · MCAP $12M · 100% circulating · Model $5M · +125%": "Gains Network · FDV $12M · 시총 $12M · 유통 100% · 모델 $5M · +125%",
    "Open interest vs circulating market cap, log-log scatter with power-law fit": "미결제약정 대 유통 시가총액, 거듭제곱 법칙 적합선을 넣은 로그–로그 산점도",
    "Same estimated market cap. Fewer tokens released at TGE means a higher FDV.": "추정 시가총액은 같습니다. TGE에 풀리는 토큰이 적을수록 FDV가 높아집니다.",
