    "Volume and open interest flow into implied fees, treasury, and buyback-burn": "거래량과 미결제약정이 추정 수수료, 트레저리, 바이백·소각으로 흐릅니다",
    "Activity is coinciding with faster treasury inflow than the recent baseline.": "최근 기준선보다 빠른 트레저리 유입과 활동이 함께 나타나고 있습니다.",
    "ApeX Protocol · FDV $107M · MCAP $33M · 31% circulating · Model $141M · -77%": "ApeX Protocol · FDV $107M · 시총 $33M · 유통 31% · 모델 $141M · -77%",
    "Every objection a desk raises about this page, stated before it gets raised.": "이 페이지에 대해 데스크가 제기할 모든 반론을, 제기되기 전에 밝힙니다.",
    "Lighter: $5.01M of trader fees splits into $3.81M booked and $1.21M paid out": "Lighter: 트레이더 수수료 $5.01M이 장부 계상 $3.81M과 지급 $1.21M으로 나뉩니다",
    "creates settlement pools. It is infrastructure, not a direct revenue wallet.": "는 정산 풀을 생성합니다. 인프라이지 매출 지갑이 아닙니다.",
    "Long versus short open interest across the largest single-name equity markets": "최대 개별 종목 주식 마켓들의 롱 대 숏 미결제약정",
    "Open interest versus 24 hour volume for tracked perpetual DEXs, log-log scale": "추적 대상 무기한 DEX의 미결제약정 대 24시간 거래량, 로그–로그 눈금",
    "Variational accepting VAR as collateral, and a haircut. Neither is published.": "Variational이 VAR을 담보로 받아주는 것, 그리고 담보 인정 비율. 둘 다 공개되지 않았습니다.",
    "Variational is #3 of 15 by open interest. 1.5× Lighter OI · 9.5× Extended OI.": "Variational은 미결제약정 기준 15개 중 3위입니다. Lighter OI의 1.5배 · Extended OI의 9.5배.",
    "; the 14-day chart is calculated independently from on-chain treasury history.": "; 14일 차트는 온체인 트레저리 이력에서 독립적으로 계산했습니다.",
    "Every series uses its own first disclosed value, so starting dates can differ.": "모든 시리즈는 각자의 첫 공시값을 기준으로 하므로 시작 날짜가 다를 수 있습니다.",
    "Traders pay spreads. Subtract market-making costs and rewards. What remains is": "트레이더가 스프레드를 냅니다. 여기서 마켓메이킹 비용과 보상을 뺍니다. 남는 것이",
    "less leaks out of the pool · but paying liquidity is what makes the pool exist": "풀에서 새어나가는 게 적음 · 다만 유동성에 지급하는 것이 풀을 존재하게 함",
    "A longer bar means that metric jumps around more between reports. This measures": "막대가 길수록 그 지표가 리포트 간에 더 요동친다는 뜻입니다. 이건",
    "Price as a multiple of listing price with swing highs and lows marked by arrows": "상장가 배수로 본 가격, 고점·저점 전환을 화살표로 표시",
    "newest first · each value includes its change from the previous matching report": "최신순 · 각 값에는 같은 방식의 직전 리포트 대비 변화가 붙습니다",
    "same badge = same source, comparable · different badges = different measurement": "같은 배지 = 같은 출처, 비교 가능 · 다른 배지 = 다른 측정",
    "$157.4K until the treasury reaches $8.00M. At the current 7D pace, that is about": "트레저리가 $8.00M에 닿기까지 $157.4K 남았습니다. 현재 7일 속도면 약",
    "18 original views from the 20-report analysis, updated with every new disclosure": "20개 리포트 분석에서 나온 원본 뷰 18개, 새 공시마다 갱신",
    "Variational: $5.61M of trader fees splits into $1.12M booked and $4.49M paid out": "Variational: 트레이더 수수료 $5.61M이 장부 계상 $1.12M과 지급 $4.49M으로 나뉩니다",
    "annualized net treasury inflow at Month pace · implied gross spreads $344.06M/yr": "월간 속도 기준 연환산 순 트레저리 유입 · 추정 총 스프레드 $344.06M/년",
    "api.llama.fi/v2/chart/{open-interest,derivatives}/protocol/{variational,lighter}": "api.llama.fi/v2/chart/{open-interest,derivatives}/protocol/{variational,lighter}",
