    "A month of levered longs at 0.15% a day costs $4,050 on $90K of notional before the price moves at all, and launch-week funding on a genuinely hot listing routinely runs several times that. Held all 258 days it comes to $10,206 on the two-rate model below. Spot bids over the same month cost nothing to hold. The playbook does not distinguish between the two, and at the $3–5B band — “stretch bids over a month or more” — that distinction is most of the cost.": "以 0.15% 持有一个月的杠杆多头，在 $90K 名义价值上要花 $4,050 — 这还是价格一动不动的情况。而真正火热的上市，首周资金费往往是这个数的好几倍。整整持有 258 天，按下方的两段费率模型计算是 $10,206。同样一个月的现货挂单则完全没有持有成本。playbook 并没有区分这两者，而在 $3–5B 这一档 — “分散挂单一个月以上” — 这个差别就是成本的大头。",
